function chaos(){const crises=[['BOSS','Accept “urgent” task'],['EMAIL','Sort 14 new emails'],['BILL','Pay suddenly overdue bill'],['PRINTER','Clear paper jam'],['MEETING','Decline surprise meeting'],['POP-UP','Find tiny X'],['PHONE','Answer ringing phone'],['COMPUTER','Unfreeze spreadsheet'],['COWORKER','Say “Not really” to Got a minute?']];let handled=0,active=0,iv;stage(`<div class="chaos-head"><b>OFFICE STABILITY</b><div class="big-progress"><i id="chaosBar"></i></div><span id="chaosScore">0 / 24 interruptions handled</span></div><div class="chaos-grid" id="chaosGrid"></div><p class="chaos-note">Interruptions wait for you. Ignoring them creates duplicates, because that is funnier than an instant loss.</p>`,`Final task: handle 24 interruptions. Several can pile up, but none expires and progress never resets.`,180);const spawn=()=>{if(!current||current.kind!=='chaos')return clearInterval(iv);if(active>=6)return;const c=crises[Math.floor(Math.random()*crises.length)],card=document.createElement('button');card.className='crisis-card';card.innerHTML=`<small>${c[0]} · URGENT!!!</small><b>${c[1]}</b><span>RESOLVE NOW</span>`;$('#chaosGrid').append(card);active++;card.onclick=()=>{card.classList.add('resolved');card.disabled=true;active--;handled++;$('#chaosBar').style.width=handled/24*100+'%';$('#chaosScore').textContent=`${handled} / 24 interruptions handled`;beep();setTimeout(()=>card.remove(),220);if(handled===8)randomAd();if(handled===16)randomInterrupt();if(handled>=24){clearInterval(iv);setTimeout(()=>win('The office survived. Your boss has called this a successful normal day.'),450)}}};spawn();spawn();spawn();iv=setInterval(spawn,700)}
function generic(k){const configs={cables:['Connect the labeled plugs in order: A, C, B, D.',['A','C','B','D']],groceries:['Pack items from heaviest to lightest: cans, milk, eggs, bread.',['cans','milk','eggs','bread']],taxes:['Enter the sacred sequence: W2, 1099, 1040, regret.',['W2','1099','1040','regret']],furniture:['Assemble in order: dowel, screw, cam, sigh.',['dowel','screw','cam','sigh']],headphones:['Undo knots in order: 3, 1, 4, 2.',['3','1','4','2']]};const [brief,seq]=configs[k];let choices=[...seq].sort(()=>Math.random()-.5),chosen=[];stage(`<p style="font-size:11px;text-align:center">${brief}</p><div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:40px 0">${choices.map(x=>`<button class="primary choice">${x}</button>`).join('')}</div><p id="sequence" style="text-align:center;color:#71808c;font:11px monospace">SEQUENCE: —</p>`,`${brief} One mistake resets all progress.`,k==='taxes'?45:60);$$('.choice').forEach(b=>b.onclick=()=>{chosen.push(b.textContent);b.disabled=true;b.style.opacity=.35;$('#sequence').textContent='SEQUENCE: '+chosen.join(' → ');if(chosen.some((x,i)=>x!==seq[i]))return fail('Procedure violation. All previous work has been respectfully destroyed.');if(chosen.length===seq.length)win('The procedure succeeded against all reasonable expectations.');});if(['taxes','furniture'].includes(k))setTimeout(()=>current&&randomAd(),4000)}
function randomAd(){if(state.purchases.includes('adblock')&&adBlocksUsed++===0){toast('POPUP BLOCKED','Budget Ad Blocker stopped a suspicious offer.');return}const ads=[['BANK SECURITY','Account locked! Act in 2 minutes','Send your password and favorite lunch immediately.'],['CEO REQUEST','Buy $900 in gift cards','The CEO says not to call or ask why.'],['TECH SUPPORT','We detected 47 viruses','Call Definitely Microsoft and pay in cryptocurrency.'],['PRIZE CENTER','You won a company car','Pay a tiny $499 delivery fee to claim it.'],['INVOICE ALERT','Past-due invoice.exe attached','Enable macros so Accounting can steal your files faster.'],['CRYPTO DESK','Guaranteed 900% return today','Risk-free except for all of the risk.'],['HR BENEFITS','Confirm payroll information','Enter your bank login into this tasteful neon form.']];const copy=ads[Math.floor(Math.random()*ads.length)],ad=document.createElement('div');ad.className='ad-popup scam-ad';ad.style.left=8+Math.random()*38+'%';ad.style.top=20+Math.random()*38+'%';ad.innerHTML=`<button class="x">×</button><span class="eyebrow">${copy[0]}</span><h3>${copy[1]}</h3><p style="font-size:10px">${copy[2]}</p><button class="primary">CLAIM / FIX NOW</button>`;$('#taskStage').append(ad);ad.querySelector('.x').onclick=()=>ad.remove();ad.querySelector('.primary').onclick=()=>{toast('SCAM CLICKED','That button was spectacularly unsafe. Close it with the tiny X.');beep('bad')}}
function randomInterrupt(){const n=document.createElement('div');n.className='interrupt';n.style.left=Math.random()*60+15+'%';n.style.top=Math.random()*55+15+'%';n.innerHTML='<span class="eyebrow">CALENDAR REMINDER</span><h3>Meeting: Meeting Planning</h3><p style="font-size:10px">This meeting started 3 minutes ago.</p><button class="primary">Dismiss (politely)</button>';$('#interruptLayer').append(n);n.querySelector('button').onclick=()=>n.remove();setTimeout(()=>n.remove(),8000)}
invoices=function(){const rows=[['INV-1042','Northstar Paper','248.50'],['INV-1043',"Gary's Toner",'91.20'],['INV-1044','Chair Logistics','630.00']];stage(`<div class="spreadsheet-app"><div class="sheet-toolbar"><b>Invoice_Entry_FIXED.xls</b><span>Click source cells to transfer</span></div><table class="source-grid"><caption>SOURCE INVOICES</caption><tr><th>Invoice</th><th>Vendor</th><th>Amount</th></tr>${rows.map((r,i)=>`<tr>${r.map((v,j)=>`<td data-row="${i}" data-col="${j}">${v}</td>`).join('')}</tr>`).join('')}</table><table class="dest-grid"><caption>ACCOUNTS PAYABLE</caption>${rows.map((r,i)=>`<tr>${r.map((v,j)=>`<td><input readonly data-row="${i}" data-col="${j}" data-answer="${v.replace(/"/g,'&quot;')}"></td>`).join('')}</tr>`).join('')}<tr><td colspan="2">Required formula</td><td><button id="sheetFormula">Insert SUM formula</button></td></tr></table><div id="sheetErrors" class="sheet-errors">Click each source cell once, then insert the formula.</div><button class="primary" id="saveInvoices">Validate & Save</button></div>`,`Transfer all nine source cells, insert the formula, and save. Each source cell goes directly to its matching destination.`,165);let formula=false;$$('.source-grid [data-row]').forEach(c=>c.onclick=()=>{const dest=$(`.dest-grid input[data-row="${c.dataset.row}"][data-col="${c.dataset.col}"]`);dest.value=c.textContent;c.classList.add('copied');dest.classList.remove('cell-error')});$('#sheetFormula').onclick=()=>{formula=true;$('#sheetFormula').textContent='=SUM(C2:C4) ✓';$('#sheetFormula').disabled=true};$('#saveInvoices').onclick=()=>{const bad=$$('.dest-grid input').filter(i=>i.value!==i.dataset.answer);bad.forEach(i=>i.classList.add('cell-error'));if(bad.length||!formula){$('#sheetErrors').textContent=`Still needed: ${bad.length} cell(s)${formula?'':' and the SUM formula'}.`;return toast('SPREADSHEET INCOMPLETE','Highlighted cells still need transferring.')}win('Spreadsheet saved without eating any cells. Accounting is unsettled.')}};
copyData=function(){const vals=[['A2','Q4-88'],['B2','17.40'],['C2','PENDING'],['A3','A-104'],['B3','YES'],['C3','08/03/2026'],['A4','WEST'],['B4','0042']];stage(`<div class="spreadsheet-app"><div class="sheet-toolbar"><b>Workbook Transfer — Repaired</b><span id="copyCount">0 / 8 transferred</span></div><p class="sheet-help">Click each source value. It will safely transfer to the matching destination cell.</p><div class="tab-sheet active">${vals.map(v=>`<button class="source-cell" data-cell="${v[0]}" data-value="${v[1]}"><small>${v[0]}</small>${v[1]}</button>`).join('')}</div><div class="tab-sheet active" id="destSheet">${vals.map(v=>`<label><small>${v[0]}</small><input readonly data-cell="${v[0]}" data-answer="${v[1]}"></label>`).join('')}</div><label class="paste-policy">PASTE METHOD <select id="pasteMode"><option>Choose method…</option><option>Values only</option></select></label><button class="primary" id="copySave">Complete transfer</button></div>`,`Transfer eight cells and select Values only. The repaired workbook no longer loses its clipboard between tabs.`,165);let done=0;$$('.source-cell').forEach(b=>b.onclick=()=>{const input=$(`#destSheet input[data-cell="${b.dataset.cell}"]`);if(!input.value){input.value=b.dataset.value;b.disabled=true;b.classList.add('copied');$('#copyCount').textContent=`${++done} / 8 transferred`}});$('#copySave').onclick=()=>{if(done!==vals.length||$('#pasteMode').value!=='Values only')return toast('TRANSFER INCOMPLETE','Transfer every cell and choose Values only.');win('Data transferred. The repaired workbook remained in one piece.')}};
printer=function(){stage(`<div class="printer-workbench"><div class="printer-model"><div class="printer-top"><div class="paper-output">STATUS REPORT<br>PLEASE DO NOT PRINT</div></div><div class="printer-body"><div class="printer-screen" id="printerScreen">SLEEPING — PRESS POWER</div><div class="printer-panel"><button data-p="power">POWER</button><button data-p="resume">RESUME</button><button data-p="cancel">CANCEL</button><button data-p="wifi">WI-FI</button></div><button class="printer-door" data-p="door">FRONT ACCESS DOOR</button><div class="toner-bay" id="tonerBay"><button data-p="jam">REMOVE VISIBLE JAM</button><button data-p="toner">SHAKE CYAN TONER</button></div><button class="paper-tray" data-p="tray">PAPER TRAY 2 <span id="paperStack"></span></button></div></div><aside class="printer-ticket"><b>HELP DESK TICKET #404</b><ol><li>Wake printer</li><li>Open front door and remove jam</li><li>Close front door</li><li>Open Tray 2 and load paper</li><li>Close tray, press Resume, print test</li></ol><button class="primary" data-p="test">PRINT TEST PAGE</button></aside></div><p id="printerLog" class="printer-log">The printer is pretending not to hear you.</p>`,`Repair the physical printer using the help ticket. Wrong controls complain but do not erase correct work.`,115);let s={on:false,door:false,jam:false,tray:false,paper:false,resumed:false};const screen=m=>{$('#printerScreen').textContent=m;$('#printerLog').textContent=m};const wrong=m=>{screen(m);toast('PRINTER DISAGREES','Nothing was reset. The printer simply wanted attention.');beep('bad')};$$('[data-p]').forEach(b=>b.onclick=()=>{const a=b.dataset.p;if(a==='power'){s.on=true;b.classList.add('pressed');return screen('ERROR: JAM. ALSO LOW PAPER. ALSO FINE.')}if(!s.on)return wrong('NO RESPONSE — the printer is asleep.');if(a==='door'){s.door=!s.door;$('.printer-model').classList.toggle('door-open',s.door);return screen(s.door?'DOOR OPEN — JAM VISIBLE':s.jam?'DOOR CLOSED — CHECK TRAY':'DOOR CLOSED WITH JAM STILL INSIDE')}if(a==='jam'){if(!s.door)return wrong('OPEN FRONT DOOR FIRST');s.jam=true;b.disabled=true;b.textContent='JAM REMOVED ✓';return screen('JAM REMOVED — CLOSE DOOR')}if(a==='toner')return wrong('CYAN IS AT 94%. THAT WARNING WAS DECORATIVE.');if(a==='tray'){if(s.door)return wrong('CLOSE FRONT DOOR BEFORE OPENING TRAY');s.tray=!s.tray;$('.printer-model').classList.toggle('tray-open',s.tray);if(s.tray&&!s.paper){s.paper=true;$('#paperStack').textContent='500 SHEETS LOADED';return screen('PAPER LOADED — CLICK TRAY TO CLOSE')}return screen(s.tray?'TRAY OPEN':'TRAY CLOSED — PRESS RESUME')}if(a==='resume'){if(!s.jam||s.door||s.tray||!s.paper)return wrong('CANNOT RESUME — A PHYSICAL STEP IS INCOMPLETE');s.resumed=true;b.classList.add('pressed');return screen('READY — DEFINITELY DO NOT TRUST READY')}if(a==='cancel')return wrong('CANCELLED NOTHING SUCCESSFULLY');if(a==='wifi')return randomAd();if(a==='test'){if(!s.resumed)return wrong('TEST PAGE REFUSED — PRESS RESUME AFTER REPAIR');$('.paper-output').classList.add('printing');screen('PRINTING TEST PAGE…');setTimeout(()=>win('Printer repaired. The test page says LOW CYAN in enormous letters.'),700)}})};
function holePunchGame(){stage(`<div class="punch-desk"><div class="paper-sheet" id="punchPaper"><i></i><i></i><i></i><span>FORM 88-B</span></div><div class="punch-machine"><b>THREE-HOLE PUNCH</b><input id="punchAlign" type="range" min="0" max="100" value="15"><small>Alignment guide: target notch 63</small><button class="primary" id="punchNow">PULL HANDLE</button></div></div><p id="punchStatus">Slide the paper guide to 63, then punch.</p>`,`Align the guide with notch 63 and pull the punch handle. Near misses leave visible bad holes but can be corrected.`,95);let tries=0;$('#punchNow').onclick=()=>{const v=+$('#punchAlign').value;tries++;$('#punchPaper').style.transform=`translateX(${(v-63)*.35}px)`;if(Math.abs(v-63)<=2){$('#punchPaper').classList.add('punched');return setTimeout(()=>win('Three holes punched. The binder has, naturally, two rings.'),450)}$('#punchPaper').classList.add('bad-punch');$('#punchStatus').textContent=`Attempt ${tries}: holes missed by ${Math.abs(v-63)} notch(es). Re-align and try again.`;toast('PAPER MISALIGNED','The sheet survived. The ugly holes did not disappear.')}}
function shippingLabelGame(){const address='184 PAPERCLIP WAY',city='CHICAGO',zip='60601',tracking='1Z404000404';stage(`<div class="label-maker"><div class="label-order"><b>ORDER #TS-404</b><p>SHIP TO: ${address}<br>${city}, IL ${zip}</p><code>${tracking}</code></div><div class="label-form"><label>STREET<input id="labelStreet"></label><label>CITY<input id="labelCity"></label><label>ZIP<input id="labelZip" maxlength="5"></label><label>TRACKING<input id="labelTrack"></label><label>FORMAT<select id="labelFormat"><option>Letter paper (wrong)</option><option>4 × 6 thermal</option></select></label><button class="primary" id="printLabel">PRINT LABEL</button></div><div class="thermal-label" id="thermalLabel">LABEL PREVIEW<br><span>waiting for data</span></div></div>`,`Write out the shipping label exactly from the order card and choose 4 × 6 thermal format.`,125);$('#printLabel').onclick=()=>{const vals=[$('#labelStreet').value.trim().toUpperCase(),$('#labelCity').value.trim().toUpperCase(),$('#labelZip').value.trim(),$('#labelTrack').value.trim().toUpperCase()],ok=vals[0]===address&&vals[1]===city&&vals[2]===zip&&vals[3]===tracking&&$('#labelFormat').value==='4 × 6 thermal';if(!ok){$('#thermalLabel span').textContent='VOID — ADDRESS OR FORMAT ERROR';return toast('LABEL VOIDED','Check every field against the order card. Your typing remains.')}$('#thermalLabel').innerHTML=`${address}<br>${city}, IL ${zip}<br><b>${tracking}</b>`;$('#thermalLabel').classList.add('printed');setTimeout(()=>win('Shipping label printed. The barcode is judging your handwriting.'),550)}}
function signatureGame(){stage(`<div class="signature-desk"><div><small>REFERENCE SIGNATURE</small><canvas id="sigReference" width="420" height="140"></canvas></div><div><small>DRAW A SIMILAR SIGNATURE — mouse or touch</small><canvas id="sigCanvas" width="420" height="140"></canvas></div><p id="sigTries">3 attempts remaining</p><button id="sigClear">Clear</button><button class="primary" id="sigSubmit">Verify signature</button></div>`,`Trace a signature similar to the reference. You get three verification attempts; clearing does not consume one.`,115);const ref=$('#sigReference'),canvas=$('#sigCanvas'),rc=ref.getContext('2d'),ctx=canvas.getContext('2d'),target=x=>70-35*Math.sin(x/34)-12*Math.sin(x/11);rc.strokeStyle='#9b6b72';rc.lineWidth=4;rc.beginPath();for(let x=25;x<=395;x+=3){const y=target(x);x===25?rc.moveTo(x,y):rc.lineTo(x,y)}rc.stroke();let drawing=false,points=[],tries=3;const pos=e=>{const r=canvas.getBoundingClientRect(),p=e.touches?.[0]||e;return{x:(p.clientX-r.left)*canvas.width/r.width,y:(p.clientY-r.top)*canvas.height/r.height}};const start=e=>{e.preventDefault();drawing=true;const p=pos(e);points.push(p);ctx.beginPath();ctx.moveTo(p.x,p.y)};const move=e=>{if(!drawing)return;e.preventDefault();const p=pos(e);points.push(p);ctx.lineWidth=4;ctx.lineCap='round';ctx.strokeStyle='#18242d';ctx.lineTo(p.x,p.y);ctx.stroke()};const stop=()=>drawing=false;canvas.onpointerdown=start;canvas.onpointermove=move;canvas.onpointerup=stop;canvas.onpointerleave=stop;$('#sigClear').onclick=()=>{ctx.clearRect(0,0,420,140);points=[]};$('#sigSubmit').onclick=()=>{const wide=points.length>25&&Math.min(...points.map(p=>p.x))<65&&Math.max(...points.map(p=>p.x))>350,err=points.length?points.reduce((n,p)=>n+Math.abs(p.y-target(p.x)),0)/points.length:999;if(wide&&err<31)return win('Signature accepted. A handwriting expert sighed somewhere.');tries--;$('#sigTries').textContent=`${tries} attempt${tries===1?'':'s'} remaining · similarity ${Math.max(0,Math.round(100-err))}%`;ctx.clearRect(0,0,420,140);points=[];if(!tries)return fail('Three signatures rejected. Please regrow your handwriting and try again.');toast('SIGNATURE MISMATCH','Follow the overall wave and use most of the signature box.')}}
guidedWorkflow=function(cfg){const steps=cfg.steps,kind=current.kind;
 if(current.id==='holepunch')return holePunchGame();
 if(current.id==='labels')return shippingLabelGame();
 if(current.id==='signdocs')return signatureGame();
 if(kind==='emailops'){
  const folders=['ACTION','REFERENCE','IGNORE'];
  stage(`<div class="workflow-memo"><b>${cfg.memo}</b><p>${cfg.rule}</p></div><div class="decision-list">${steps.map((s,i)=>`<div><b>${s}</b><select data-answer="${folders[i%3]}"><option value="">Choose handling…</option>${folders.map(f=>`<option>${f}</option>`).join('')}</select></div>`).join('')}</div><button class="primary" id="workflowSubmit">Process mailbox</button>`,`Classify each message. The required destination cycles ACTION, REFERENCE, IGNORE and is shown by row color.`,130);
  $$('.decision-list>div').forEach((r,i)=>r.style.borderLeft=`5px solid ${['#c64a4a','#4381a0','#929da2'][i%3]}`);
  $('#workflowSubmit').onclick=()=>{const bad=$$('.decision-list select').filter(s=>s.value!==s.dataset.answer);bad.forEach(s=>s.classList.add('cell-error'));if(bad.length)return toast('MAILBOX DISAGREES',`${bad.length} decision(s) need another look.`);win(cfg.finish)};return
 }
 if(kind==='officeops'){
  const tools=['RED STAMP','BLUE PEN','STAPLER'],right=tools[steps.length%3];
  stage(`<div class="workflow-memo"><b>${cfg.memo}</b><p>${cfg.rule}</p></div><div class="office-checklist">${steps.map((s,i)=>`<label><input type="checkbox" data-check> ${s}<small>Station ${String.fromCharCode(65+i)}</small></label>`).join('')}</div><label class="tool-picker">AUTHORIZED TOOL <select id="officeTool"><option value="">Select tool…</option>${tools.map(t=>`<option>${t}</option>`).join('')}</select></label><button class="primary" id="workflowSubmit">Submit completed work</button>`,`Complete every station in any order, then select the authorized tool: ${right}.`,140);
  $('#workflowSubmit').onclick=()=>{const missing=$$('[data-check]').filter(x=>!x.checked);if(missing.length||$('#officeTool').value!==right)return toast('DESK INSPECTION',`${missing.length} station(s) remain or the tool is incorrect.`);win(cfg.finish)};return
 }
 if(kind==='techops'){
  const code=(current.id.toUpperCase()+'-OK').replace(/[^A-Z-]/g,'');
  stage(`<div class="security-scan"><b>${cfg.memo}</b><p>${cfg.rule}</p><div class="diagnostic-grid">${steps.map((s,i)=>`<label><input type="checkbox" data-diag> TEST ${i+1}: ${s}</label>`).join('')}</div><p>Verification token: <code>${code}</code></p><input id="diagCode" placeholder="Type token exactly"><button class="primary" id="workflowSubmit">Execute repair</button></div>`,`Run every diagnostic in any order and type the displayed verification token.`,145);
  $('#workflowSubmit').onclick=()=>{if($$('[data-diag]').some(x=>!x.checked)||$('#diagCode').value.trim().toUpperCase()!==code)return toast('DIAGNOSTIC INCOMPLETE','Run every test and copy the token exactly.');win(cfg.finish)};return
 }
 if(kind==='shipops'){
  const targets=steps.map((_,i)=>i%3+1);
  stage(`<div class="workflow-memo"><b>${cfg.memo}</b><p>${cfg.rule}</p></div><div class="shipment-controls">${steps.map((s,i)=>`<label><b>${s}</b><span>Required: ${targets[i]}</span><input type="range" min="0" max="4" value="0" data-target="${targets[i]}"><output>0</output></label>`).join('')}</div><button class="primary" id="workflowSubmit">Seal shipment</button>`,`Set each control to its printed required quantity. Controls may be adjusted in any order.`,145);
  $$('.shipment-controls input').forEach(x=>x.oninput=()=>x.nextElementSibling.value=x.value);
  $('#workflowSubmit').onclick=()=>{const bad=$$('.shipment-controls input').filter(x=>x.value!==x.dataset.target);bad.forEach(x=>x.parentElement.classList.add('control-error'));if(bad.length)return toast('MANIFEST MISMATCH',`${bad.length} quantity control(s) are incorrect.`);win(cfg.finish)};return
 }
 const picked=new Set();stage(`<div class="workflow-memo"><b>${cfg.memo}</b><p>${cfg.rule}</p></div><div class="workflow-cards">${steps.map((s,i)=>`<label><input type="checkbox" data-i="${i}"> ${s}</label>`).join('')}</div><button class="primary" id="workflowSubmit">Complete procedure</button>`,`Complete every requirement. Order is no longer the challenge.`,130);$('#workflowSubmit').onclick=()=>$$('.workflow-cards input').every(x=>x.checked)?win(cfg.finish):toast('PROCEDURE INCOMPLETE','Some requirements are still unchecked.')
};
